#!/system/bin/sh
# SPDX-License-Identifier: LicenseRef-Zairenkai-Proprietary
# Zairenkai module install script (Magisk / KernelSU / APatch).
# Copyright (C) 2026 FebriCahyaa
SKIPUNZIP=0

ui_print "- Zairenkai ZKFC installer"
ARCH64="$(getprop ro.product.cpu.abi)"
API="$(getprop ro.build.version.sdk)"
ui_print "  device abi: $ARCH64, api: $API"

if [ "$API" -lt 31 ]; then
  ui_print "! Zairenkai requires Android 12 (API 31) or newer"
  abort "  aborting"
fi

# A source checkout is not a flashable module package: the per-KMI .ko files
# are generated by the CI build and must be present in a release ZIP.
if { [ ! -d "$MODPATH/lkm" ] || [ -z "$(find "$MODPATH/lkm" -type f -name 'zkfc.ko' -print -quit 2>/dev/null)"; }; then
  if [ ! -e /dev/zkfc ]; then
    ui_print "! This package contains no ZKFC kernel module (zkfc.ko)."
    ui_print "  Download the CI-built Zairenkai-module.zip for a KMI/ABI module set."
    abort "  refusing an installation that could only enable the UI without the kernel driver"
  fi
  ui_print "- No LKM payload; using the already-present built-in ZKFC endpoint."
fi

# Prefer the directory matching the kernel's Android KMI when it is exposed.
# Some vendor kernels omit androidNN-X.Y from uname -r; in that case retain
# candidates from the same Linux family/ABI and let the kernel loader validate
# vermagic plus symbol CRCs. Do not arbitrarily claim that a KMI branch is known.
KREL="$(uname -r)"
ui_print "- Kernel: $KREL"
KERNEL_FAMILY="$(echo "$KREL" | cut -d- -f1 | awk -F. 'NF >= 2 && $1 ~ /^[0-9]+$/ && $2 ~ /^[0-9]+$/ { print $1 "." $2 }')"
# uname commonly formats KMI as 5.10.198-android13-9, not android13-5.10.
ANDROID_BRANCH="$(echo "$KREL" | grep -oE 'android[0-9]+' | head -1)"
KMI=""
if [ -n "$ANDROID_BRANCH" ] && [ -n "$KERNEL_FAMILY" ]; then
  KMI="$ANDROID_BRANCH-$KERNEL_FAMILY"
fi
ARCH64="$(getprop ro.product.cpu.abi)"
ABIDIR="arm64"
case "$ARCH64" in
  arm64*) ABIDIR="arm64" ;;
  x86_64) ABIDIR="x86_64" ;;
esac

module_release() {
  [ -f "$1" ] || return 0
  grep -a -o 'vermagic=[^[:space:]]*' "$1" 2>/dev/null | head -1 | sed 's/^vermagic=//'
}
module_family() {
  release="$(module_release "$1")"
  numeric="$(echo "$release" | cut -d- -f1)"
  echo "$numeric" | awk -F. 'NF >= 2 && $1 ~ /^[0-9]+$/ && $2 ~ /^[0-9]+$/ { print $1 "." $2 }'
}

# Refuse a misleading "enabled" installation if neither a built-in endpoint
# nor any module from the running kernel's Linux family is available.
if [ ! -e /dev/zkfc ]; then
  if [ -z "$KERNEL_FAMILY" ]; then
    ui_print "! Cannot identify the running kernel's Linux major/minor family: $KREL"
    abort "  refusing to guess which kernel module to load"
  fi
  family_match=0
  while IFS= read -r candidate; do
    [ -f "$candidate" ] || continue
    if [ "$(module_family "$candidate")" = "$KERNEL_FAMILY" ]; then
      family_match=1
      break
    fi
  done <<EOF_MODULES
$(find "$MODPATH/lkm" -type f -name 'zkfc.ko' 2>/dev/null | sort)
EOF_MODULES
  if [ "$family_match" -ne 1 ]; then
    ui_print "! No zkfc.ko candidate targets Linux $KERNEL_FAMILY."
    abort "  this module package cannot provide ZKFC for the running kernel"
  fi
fi

mkdir -p "$MODPATH/zkfc"
PRIMARY="$MODPATH/lkm/$KMI-$ABIDIR/zkfc.ko"
if [ -n "$KMI" ] && [ -f "$PRIMARY" ] && [ "$(module_family "$PRIMARY")" = "$KERNEL_FAMILY" ]; then
  cp "$PRIMARY" "$MODPATH/zkfc/zkfc.ko"
  ui_print "- Preferred KMI module staged: $KMI-$ABIDIR"
  ui_print "  Other same-family candidates are retained as runtime fallbacks."
else
  rm -f "$MODPATH/zkfc/zkfc.ko"
  if [ -n "$KMI" ]; then
    ui_print "! No primary module for $KMI/$ABIDIR in Linux family ${KERNEL_FAMILY:-unknown}."
  else
    ui_print "! Kernel release has no recognizable Android KMI branch."
  fi
  ui_print "  Compatible same-family candidates will be tried at boot; the kernel loader checks module compatibility."
fi
# Do not delete lkm candidates yet. service.sh tries matching-ABI and
# matching-major/minor modules until the kernel creates /dev/zkfc, then stops.

# Install the userspace engine.
mkdir -p /data/adb/zkfc
for abi in arm64-v8a arm64 x86_64; do
  if [ -f "$MODPATH/bin/$abi/zkfctl" ]; then
    cp "$MODPATH/bin/$abi/zkfctl" /data/adb/zkfc/zkfctl
    break
  fi
done

# ---- Install the zperfd performance engine + profile catalog ----
mkdir -p /data/adb/zperf/catalog /data/adb/zperf/database
for abi in arm64-v8a arm64 x86_64; do
  if [ -f "$MODPATH/bin/$abi/zperfd" ]; then
    cp "$MODPATH/bin/$abi/zperfd" /data/adb/zperf/zperfd
    ui_print "- zperfd engine installed ($abi)"
    break
  fi
done
if [ -d "$MODPATH/zperf/catalog" ]; then
  cp "$MODPATH"/zperf/catalog/*.toml /data/adb/zperf/catalog/ 2>/dev/null
fi
if [ -d "$MODPATH/zperf/database" ]; then
  cp -R "$MODPATH/zperf/database/." /data/adb/zperf/database/
fi
# Scene / vtools external-scheduler contract.
if [ -f "$MODPATH/zperf/powercfg.sh" ]; then
  cp "$MODPATH/zperf/powercfg.sh" /data/powercfg.sh && chmod 0755 /data/powercfg.sh
  [ -f "$MODPATH/zperf/powercfg.json" ] && cp "$MODPATH/zperf/powercfg.json" /data/powercfg.json
  ui_print "- Scene powercfg contract installed (/data/powercfg.sh)"
fi
[ -f /data/adb/zperf/mode ] || echo balance > /data/adb/zperf/mode
chmod 0700 /data/adb/zperf 2>/dev/null || true
chmod 0600 /data/adb/zperf/mode 2>/dev/null || true

rm -rf "$MODPATH/bin"
set_perm /data/adb/zkfc/zkfctl 0 0 0755 u:object_r:system_file:s0 2>/dev/null
[ -f /data/adb/zperf/zperfd ] && set_perm /data/adb/zperf/zperfd 0 0 0755 u:object_r:system_file:s0 2>/dev/null
set_perm_recursive "$MODPATH" 0 0 0755 0644

ui_print "- Installed zkfctl to /data/adb/zkfc/zkfctl"
ui_print "- Reboot, then open the Zairenkai app"
